(function(root){'use strict';
const STORE='scm-shared-data-v1',CHANNEL='scm-data-updated-v1',listeners=new Set();let opened;
function open(){if(!opened)opened=new Promise((resolve,reject)=>{const request=indexedDB.open(STORE,1);request.onupgradeneeded=()=>request.result.createObjectStore('workspace');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('브라우저 데이터 저장소를 열 수 없습니다.'))});return opened}
async function get(key='current'){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace'),request=tx.objectStore('workspace').get(key);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error)})}
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel(CHANNEL):null;
function emit(record){for(const fn of listeners)fn(record);if(channel)channel.postMessage({revision:record.revision});try{localStorage.setItem(CHANNEL,record.revision)}catch(e){}}
async function save(bytes,meta={},expected){const db=await open(),data=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);if(data.byteLength>100*1024*1024)throw Error('연결 DB는 100MB 이하로 저장해 주세요.');const record={bytes:data,meta:{...meta,updatedAt:new Date().toISOString()},revision:crypto.randomUUID()};await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite'),store=tx.objectStore('workspace'),request=store.get('current');let conflict=false;request.onsuccess=()=>{const previous=request.result;if(expected!==undefined&&(previous?.revision||null)!==expected){conflict=true;tx.abort();return}if(previous)store.put(previous,'previous');store.put(record,'current')};tx.oncomplete=resolve;tx.onabort=()=>reject(Error(conflict?'다른 탭에서 데이터가 바뀌었습니다. 새로 확인한 뒤 다시 반영하세요.':'브라우저에 저장하지 못했습니다. 저장 공간을 확인하세요.'));tx.onerror=()=>{}});emit(record);return record}
async function restore(){const [current,previous]=await Promise.all([get(),get('previous')]);if(!previous)throw Error('복원할 이전 연결 데이터가 없습니다.');return save(previous.bytes,{...previous.meta,name:previous.meta.name+' · 복원'},current?.revision||null)}
function subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn)}
async function external(){try{const record=await get();if(record)for(const fn of listeners)fn(record)}catch(e){}}
if(channel)channel.onmessage=external;addEventListener('storage',e=>{if(e.key===CHANNEL)external()});
let sqlPromise;function sql(){return sqlPromise||(sqlPromise=initSqlJs({locateFile:name=>new URL('assets/'+name,scriptBase).href}))}const scriptBase=new URL('.',document.currentScript.src);
async function template(empty=false){const response=await fetch(new URL(empty?'data/empty.db.gz':'assets/scm.db.gz',scriptBase));if(!response.ok)throw Error('기본 DB를 불러오지 못했습니다.');return new Uint8Array(await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())}
function rows(db,query,params=[]){const stmt=db.prepare(query);try{stmt.bind(params);const out=[];while(stmt.step())out.push(stmt.getAsObject());return out}finally{stmt.free()}}
function check(db){if(rows(db,'PRAGMA application_id')[0].application_id!==1396919620)throw Error('SCM DB 형식이 아닙니다. 원본 CSV·Excel은 데이터 연결 화면에서 선택하세요.');for(const t of ['inventory_daily','location_inventory_daily','product_master_daily','purchase_order_daily','purchase_receipt_daily','stockout_daily','column_dictionary'])if(!rows(db,'SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=?',[t]).length)throw Error('필수 테이블이 없습니다: '+t);db.exec('SELECT * FROM v_sku_day LIMIT 0');if(rows(db,'PRAGMA quick_check')[0].quick_check!=='ok')throw Error('DB 무결성 검사에 실패했습니다.');return true}
root.SCMHub={get,save,restore,subscribe,sql,template,rows,check};
})(window);
